mapper.delete:
delete from MST_FUND_MARKET_INFO
where FUND_CODE = #{fundCode,jdbcType=VARCHAR}
and VALUE_DATE = to_date(#{valueDate,jdbcType=VARCHAR},'yyyy-MM-dd')

mapper.select:
select distinct t.FINPROD_ID id, t.FINPROD_ABBR text from FIN_PRODUCT t where t.FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR}
and t.FINPROD_ID = #{initValue}
and (lower(t.FINPROD_ID) like '%' || lower(#{search}) || '%' or lower(t.FINPROD_ABBR) like '%' || lower(#{search}) || '%' or lower(t.FINPROD_NAME) like '%' || lower(#{search}) || '%')

select distinct
t.FINPROD_MARKET_ID id,
t.FINPROD_ABBR text
from FIN_PRODUCT t
where t.FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR}

	and t.FINPROD_ID = #{finprodId}
